// ─── JsonUtility (built-in de Unity) ───
// ✅ Rápido, sin instalación, funciona en todas las plataformas
// ❌ NO soporta Dictionary directamente
// ❌ NO soporta tipos abstractos ni interfaces
// ❌ Requiere [System.Serializable] en las clases

[System.Serializable]
public class ItemData { public string id; public int price; }

string json = JsonUtility.ToJson(item);          // objeto → JSON
ItemData item = JsonUtility.FromJson<ItemData>(json); // JSON → objeto

// ─── Newtonsoft Json.NET (via Package Manager) ───
// ✅ Soporta Dictionary<string, T>
// ✅ Soporta tipos abstractos, interfaces, LINQ
// ✅ No necesita [System.Serializable]
// ⚠️ Requiere instalación desde Package Manager o NuGet

using Newtonsoft.Json;
var dict = JsonConvert.DeserializeObject<Dictionary<string, ItemData>>(json);
string jsonOut = JsonConvert.SerializeObject(dict, Formatting.Indented);

// JSON con datos anidados
// items.json
/*
{
  "items": [
    {
      "id": "sword_01",
      "name": "Espada de Hierro",
      "stats": { "attack": 25, "durability": 100 },
      "tags": ["weapon", "melee"]
    }
  ]
}
*/

// Clases C# para parsear datos anidados con JsonUtility
[System.Serializable]
public class WeaponStats
{
    public int attack;
    public int durability;
}

[System.Serializable]
public class ItemData
{
    public string id;
    public string name;
    public WeaponStats stats;  // objeto anidado
    public string[] tags;      // array anidado
}

[System.Serializable]
public class ItemDatabase
{
    public ItemData[] items; // objeto raíz requerido por JsonUtility
}

// Carga y parseo
TextAsset file = Resources.Load<TextAsset>("items");
ItemDatabase db = JsonUtility.FromJson<ItemDatabase>(file.text);

